import { bootProblemsMessage } from "../../../core/codegen-core/node-server-runtime/boundary-hooks.js";
import { SERVER_RUNTIME_VERSION } from "./version.js";

// The boot check's first step (ADR 0025, G3): the version the api's generated code carries against this runtime's.
// The runtime serves the code of its own `major.minor` written by a generator at its patch or an earlier one.

/** The rule id of a boot refused for code generated by another version. */
export const GENERATED_FOR_OTHER_VERSION = "runtime.generated-for-other-version";

const RELEASE_VERSION = /^(\d+)\.(\d+)\.(\d+)$/;

/** The part of an api the version check reads. */
export interface VersionedApi {
  readonly id: string;
  readonly generatorVersion: string;
}

/** Throws before any other check when the api was generated by a version this runtime does not serve. */
export function refuseCodeOfOtherVersion(
  api: VersionedApi,
  installedVersion: string = SERVER_RUNTIME_VERSION,
): void {
  if (servesGeneratedVersion(installedVersion, api.generatorVersion)) return;

  throw new Error(
    bootProblemsMessage(api, [
      {
        problem: `${GENERATED_FOR_OTHER_VERSION}: The \`${api.id}\` boundary was generated by seampact \`${api.generatorVersion}\`; the installed runtime is \`${installedVersion}\``,
        fix: `run \`seampact generate\` again with the generator at \`${installedVersion}\`, or install the runtime at \`${api.generatorVersion}\` or a later patch of it`,
      },
    ]),
  );
}

// The same version passes; otherwise both must be release versions of one `major.minor`, the runtime's patch at or
// above the generator's. A prerelease version passes only against itself.
function servesGeneratedVersion(installedVersion: string, generatedVersion: string): boolean {
  if (installedVersion === generatedVersion) return true;

  const installed = RELEASE_VERSION.exec(installedVersion);
  const generated = RELEASE_VERSION.exec(generatedVersion);

  if (installed === null || generated === null) return false;

  return (
    installed[1] === generated[1] &&
    installed[2] === generated[2] &&
    Number(installed[3]) >= Number(generated[3])
  );
}
